package cn.mop.persistence;

import cn.mop.domain.*;
import cn.mop.domain.ticketcomment.*;
import cn.mop.domain.ticketcomment.TicketCommentRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Real V11/runtime-role comments over clearly synthetic report parents. No external provider or state transition. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresTicketCommentIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresTicketCommentRepository notes;static String engineer,viewer,admin,tadmin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);notes=new PostgresTicketCommentRepository(pool,platform);engineer=actor("msp");viewer=actor("viewer");admin=actor("padmin");tadmin=actor("tadmin");assertEquals(List.of(),notes.readinessProblems());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor){return new Access(actor,TENANT,platform.membership(actor,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static String ticket(){return ticket(viewer);}
    static String ticket(String reporter){String key=UUID.randomUUID().toString();var report=new CustomerReport("PUBLIC-COMMENT-TEST-"+key,"虚构公开评论测试父登记","网络不通","individual","虚构联系人","+00 000","normal",null,List.of());var registered=(CustomerReportRegistration)platform.idempotent(reporter,TENANT,"POST /integration/comment-parent",key,"a".repeat(64),()->{var value=platform.registerCustomerReport(TENANT,reporter,report);platform.audit(reporter,TENANT,"integration.comment_parent.create","ticket",value.ticketId(),"SUCCEEDED","SYNTHETIC_ONLY",key);return value;});return registered.ticketId();}
    static long version(String ticket){return ((Number)platform.ticket(TENANT,engineer,ticket).orElseThrow().get("version")).longValue();}
    static Object command(PostgresPlatformRepository p,Access a,String parent,String route,String key,String hash,Supplier<Object> action){var guard=new PostgresTicketCommentRepository(pool,p);return p.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->guard.authorizeCurrentAccess(a,parent),action);}
    static Entry create(String ticket,String actor,String text){Access a=access(actor);return (Entry)command(platform,a,ticket,"POST /integration/comments/"+ticket,UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,ticket,version(ticket),new TicketComment(text)));}
    static long audits(String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid AND payload->>'action'='ticket.comment.create' AND payload->>'resource_id'=?")){s.setString(1,TENANT);s.setString(2,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    @Test void immutableRawNoteAndFingerprintRoundTripWithIndependentConnection()throws Exception{String parent=ticket();Entry note=create(parent,engineer,"  内部说明😀\n原文\t ");assertEquals(TicketCommentAccess.AuthorKind.ENGINEER,note.authorKind());assertEquals(TENANT,note.tenantId());assertEquals(parent,note.ticketId());assertEquals(1,note.observedTicketVersion());assertEquals("  内部说明😀\n原文\t ",note.comment().text());assertEquals(note,new PostgresTicketCommentRepository(pool,new PostgresPlatformRepository(pool,mapper)).get(access(admin),parent,note.id()));assertEquals(1,audits(note.id()));}
    @Test void commentsStaySeparateFromParentWorkflowDtoAndPrivateInternalNotes()throws Exception{
        String parent=ticket();var internalBefore=platform.ticket(TENANT,engineer,parent).orElseThrow();var customerBefore=platform.ticket(TENANT,viewer,parent).orElseThrow();
        var privateNotes=new PostgresInternalTicketNoteRepository(pool,platform);var privateAccess=new cn.mop.domain.ticketnote.InternalTicketNoteRepository.Access(engineer,TENANT,access(engineer).permissionVersion(),UUID.randomUUID().toString());
        platform.idempotent(engineer,TENANT,"POST /integration/private-note/"+parent,UUID.randomUUID().toString(),"c".repeat(64),privateAccess.permissionVersion(),()->privateNotes.create(privateAccess,parent,1,new cn.mop.domain.ticketnote.InternalTicketNote("INTERNAL_ONLY_SENTINEL")));
        create(parent,engineer,"公开说明");create(parent,viewer,"客户补充");assertEquals(internalBefore,platform.ticket(TENANT,engineer,parent).orElseThrow());assertEquals(customerBefore,platform.ticket(TENANT,viewer,parent).orElseThrow());
        var published=notes.list(access(viewer),parent,10,null,null);assertEquals(2,published.size());String payload=json(published).toString();assertFalse(payload.contains("INTERNAL_ONLY_SENTINEL"));assertFalse(payload.contains("actor_id"));assertFalse(payload.contains("display_name"));
        assertEquals(1,privateNotes.list(privateAccess,parent,10,null,null).size());
    }
    @Test void onlyReporterAndInternalRolesCanReadOrContributeAndAttributionIsGeneric(){
        String parent=ticket();Entry engineerComment=create(parent,engineer,"工程师公开说明"),adminComment=create(parent,admin,"管理人员公开说明"),customerComment=create(parent,viewer,"报障人补充");
        assertEquals("工程师",notes.get(access(viewer),parent,engineerComment.id()).authorKind().publicLabel());assertEquals("工程师",notes.get(access(viewer),parent,adminComment.id()).authorKind().publicLabel());assertEquals("报障人",notes.get(access(engineer),parent,customerComment.id()).authorKind().publicLabel());
        Access other=access(tadmin);assertEquals(404,assertThrows(DomainException.class,()->notes.list(other,parent,10,null,null)).status);assertEquals(404,assertThrows(DomainException.class,()->notes.get(other,parent,engineerComment.id())).status);assertEquals(404,assertThrows(DomainException.class,()->command(platform,other,parent,"POST /integration/other-reporter",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(other,parent,1,new TicketComment("forbidden")))).status);
        String own=ticket(tadmin);assertEquals(TicketCommentAccess.AuthorKind.REPORTER,create(own,tadmin,"本人登记补充").authorKind());assertEquals(404,assertThrows(DomainException.class,()->notes.list(access(viewer),own,10,null,null)).status);
    }
    @Test void originalKeyReplayKeepsOriginalReceiptAfterLaterNoteWithoutDuplicateAudit()throws Exception{String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/note-replay/"+parent;Access a=access(engineer);Object first=command(platform,a,parent,route,key,"a".repeat(64),()->notes.create(a,parent,1,new TicketComment("first")));create(parent,admin,"later");Object replay=command(platform,a,parent,route,key,"a".repeat(64),()->{throw new AssertionError("Replay must not execute");});assertEquals(json(first),json(replay));assertEquals(2,notes.list(a,parent,10,null,null).size());assertEquals(1,audits(((Entry)first).id()));assertEquals(409,assertThrows(DomainException.class,()->command(platform,a,parent,route,key,"b".repeat(64),()->null)).status);}
    @Test void wrongParentVersionDoesNotWriteAndUnguardedTransactionCannotRun(){String parent=ticket();Access a=access(engineer);assertThrows(IllegalStateException.class,()->notes.create(a,parent,1,new TicketComment("unguarded")));assertEquals(409,assertThrows(DomainException.class,()->command(platform,a,parent,"POST /integration/note-conflict",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,parent,2,new TicketComment("stale")))).status);assertTrue(notes.list(a,parent,10,null,null).isEmpty());}
    @Test void foreignParentAndWrongParentNoteAre404()throws SQLException{String parent=ticket(),other=ticket();Entry note=create(parent,engineer,"scope");Access a=access(engineer);assertEquals(404,assertThrows(DomainException.class,()->notes.get(a,other,note.id())).status);String foreign;try(var c=pool.getConnection();var s=c.prepareStatement("SELECT id::text FROM public.mop_ticket WHERE tenant_id=?::uuid LIMIT 1")){s.setString(1,OTHER);try(var r=s.executeQuery()){assertTrue(r.next());foreign=r.getString(1);}}assertEquals(404,assertThrows(DomainException.class,()->notes.list(a,foreign,10,null,null)).status);assertEquals(404,assertThrows(DomainException.class,()->command(platform,a,parent,"POST /integration/foreign-note",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(a,foreign,1,new TicketComment("foreign")))).status);}
    @Test void stalePermissionAndUnknownMembershipFailClosed(){String parent=ticket();Access a=access(engineer),stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->notes.list(stale,parent,10,null,null)).status);assertEquals(401,assertThrows(DomainException.class,()->notes.list(new Access(UUID.randomUUID().toString(),TENANT,1,"synthetic"),parent,10,null,null)).status);assertEquals(401,assertThrows(DomainException.class,()->command(platform,stale,parent,"POST /integration/stale-note",UUID.randomUUID().toString(),"a".repeat(64),()->notes.create(stale,parent,1,new TicketComment("stale")))).status);}
    @Test void downstreamFailureRollsBackNoteAuditAndReplayThenSameKeyCanSucceed()throws Exception{String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/rollback-note/"+parent;Access a=access(engineer);Entry[] attempted=new Entry[1];assertThrows(IllegalStateException.class,()->command(platform,a,parent,route,key,"a".repeat(64),()->{attempted[0]=notes.create(a,parent,1,new TicketComment("rollback"));throw new IllegalStateException("Synthetic downstream failure");}));assertTrue(notes.list(a,parent,10,null,null).isEmpty());assertEquals(0,audits(attempted[0].id()));Entry saved=(Entry)command(platform,a,parent,route,key,"a".repeat(64),()->notes.create(a,parent,1,new TicketComment("rollback")));assertEquals(1,audits(saved.id()));assertEquals(1,notes.list(a,parent,10,null,null).size());}
    @Test void concurrentSameKeyAcrossIndependentConnectionsCommitsExactlyOneNote()throws Exception{String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/concurrent-note/"+parent;Access a=access(engineer);ExecutorService executor=Executors.newFixedThreadPool(2);CountDownLatch ready=new CountDownLatch(2),start=new CountDownLatch(1);try{List<Future<Object>> pending=new ArrayList<>();for(int i=0;i<2;i++)pending.add(executor.submit(()->{var p=new PostgresPlatformRepository(pool,mapper);var n=new PostgresTicketCommentRepository(pool,p);ready.countDown();start.await();return command(p,a,parent,route,key,"a".repeat(64),()->n.create(a,parent,1,new TicketComment("same original request")));}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();assertEquals(json(pending.get(0).get(15,TimeUnit.SECONDS)),json(pending.get(1).get(15,TimeUnit.SECONDS)));var all=notes.list(a,parent,10,null,null);assertEquals(1,all.size());assertEquals(1,audits(all.get(0).id()));}finally{executor.shutdownNow();}}
    @Test void independentConcurrentNotesRemainSeparateWithoutChangingObservedParentVersion()throws Exception{String parent=ticket();ExecutorService executor=Executors.newFixedThreadPool(2);try{var a=executor.submit(()->create(parent,engineer,"note-a"));var b=executor.submit(()->create(parent,viewer,"comment-b"));assertNotEquals(a.get(15,TimeUnit.SECONDS).id(),b.get(15,TimeUnit.SECONDS).id());assertEquals(1,version(parent));assertEquals(2,notes.list(access(engineer),parent,10,null,null).size());}finally{executor.shutdownNow();}}
    @Test void boundedCreationCursorHasNoDuplicatesAndRejectsMalformedBoundaries(){String parent=ticket();for(int i=0;i<4;i++)create(parent,engineer,"page-"+i);Access a=access(engineer);var first=notes.list(a,parent,2,null,null);Entry tail=first.get(1);var second=notes.list(a,parent,2,tail.createdAt(),tail.id());assertEquals(2,second.size());assertTrue(first.stream().noneMatch(x->second.stream().anyMatch(y->x.id().equals(y.id()))));assertEquals(400,assertThrows(DomainException.class,()->notes.list(a,parent,102,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->notes.list(a,parent,10,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->notes.list(a,parent,10,Instant.EPOCH.plusNanos(1),tail.id())).status);}
    @Test void maximumUnicodeNoteIsStoredWithoutLoss(){String parent=ticket();String text="😀".repeat(2000);Entry note=create(parent,engineer,text);assertEquals(text,notes.get(access(admin),parent,note.id()).comment().text());assertEquals(new TicketComment(text).sha256(),note.comment().sha256());}
    @Test void successfulReadsDoNotAppendAuditOrExposeActorMetadata()throws Exception{
        String parent=ticket();Entry comment=create(parent,engineer,"公开可见文字");long before=auditCount();notes.list(access(viewer),parent,10,null,null);Entry current=notes.get(access(viewer),parent,comment.id());assertEquals(before,auditCount());var data=json(current);assertFalse(data.has("actor_id"));assertFalse(data.has("actorId"));assertFalse(data.has("author_name"));assertEquals("ENGINEER",data.path("author_kind").asText());
    }
    static long auditCount()throws SQLException{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_audit")){r.next();return r.getLong(1);}}
    static HikariDataSource singlePool(){var cfg=new HikariConfig();cfg.setJdbcUrl(System.getenv("SPRING_DATASOURCE_URL"));cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(1);cfg.setConnectionTimeout(5000);return new HikariDataSource(cfg);}
    @Test void oneConnectionPoolCanAuthorizeParentAndReadWithoutNestedBorrow(){String parent=ticket();Entry saved=create(parent,viewer,"单连接只读");try(var single=singlePool()){var reader=new PostgresTicketCommentRepository(single,new PostgresPlatformRepository(single,mapper));assertEquals(saved,reader.get(access(admin),parent,saved.id()));assertEquals(1,reader.list(access(viewer),parent,10,null,null).size());}}
    @Test void closedRealConnectionPoolFailsReadinessAndReadsWithoutFallback(){String parent=ticket();var single=singlePool();var reader=new PostgresTicketCommentRepository(single,new PostgresPlatformRepository(single,mapper));assertEquals(List.of(),reader.readinessProblems());single.close();assertEquals(List.of("TICKET_COMMENT_SCHEMA_OR_ACCESS_UNAVAILABLE"),reader.readinessProblems());assertEquals(503,assertThrows(DomainException.class,()->reader.list(access(viewer),parent,10,null,null)).status);}
    @Test void cachedReceiptCannotBypassFreshResourceGuardAndDeniedReplayKeepsOriginal()throws Exception{
        String parent=ticket(),key=UUID.randomUUID().toString(),route="POST /integration/comment-replay-guard/"+parent;Access a=access(engineer);Entry saved=(Entry)command(platform,a,parent,route,key,"a".repeat(64),()->notes.create(a,parent,1,new TicketComment("original")));
        var guards=new java.util.concurrent.atomic.AtomicInteger();Object replay=platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,"a".repeat(64),a.permissionVersion(),()->{guards.incrementAndGet();notes.authorizeCurrentAccess(a,parent);},()->{throw new AssertionError("Do not execute cached append");});assertEquals(1,guards.get());assertEquals(json(saved),json(replay));
        String missingParent=UUID.randomUUID().toString();assertEquals(404,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,"a".repeat(64),a.permissionVersion(),()->notes.authorizeCurrentAccess(a,missingParent),()->{throw new AssertionError("Denied replay must not execute");})).status);
        assertEquals(json(saved),json(command(platform,a,parent,route,key,"a".repeat(64),()->{throw new AssertionError("Original receipt remains");})));assertEquals(1,audits(saved.id()));assertThrows(IllegalStateException.class,()->notes.authorizeCurrentAccess(a,parent));
        assertEquals(401,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,"a".repeat(64),0,()->{},()->null)).status);
    }

}
